-- prosqlbody node trees beyond plain SELECTs: joins (USING, NATURAL, outer, aliased),
-- subqueries and sublinks, CTEs (recursive too), GROUP BY / HAVING (RTE_GROUP), DISTINCT
-- (ON), windows, set operations, VALUES, functions in FROM, INSERT / UPDATE / DELETE /
-- MERGE with RETURNING and ON CONFLICT. User objects' oids are masked.
create domain sbt_dom as int check (value > 0);
create table sbt_t (x int primary key, y text, z numeric, v varchar(10), c text collate "C", d sbt_dom, arr int[]);
create table sbt_u (x int, w text);
create table sbt_b (x bigint, w text);
create view sbt_vw as select x, y from sbt_t where z > 0;
create function sbt_01() returns setof text begin atomic select w from sbt_t join sbt_u on sbt_t.x = sbt_u.x; end;
create function sbt_02() returns setof int begin atomic select x from sbt_t join sbt_u using (x); end;
create function sbt_03() returns setof text begin atomic select u.w from sbt_t t left join sbt_u u on t.x = u.x; end;
create function sbt_04() returns setof int begin atomic select x from sbt_t full join sbt_u using (x); end;
create function sbt_05() returns setof text begin atomic select y from sbt_t natural join sbt_u where w = 'a'; end;
create function sbt_06() returns setof text begin atomic select a.y from sbt_t a cross join sbt_u b right join sbt_t c on c.x = b.x; end;
create function sbt_07() returns setof text begin atomic select y from sbt_t, sbt_u where sbt_t.x = sbt_u.x; end;
create function sbt_08() returns setof bigint begin atomic select count(*) from sbt_t group by y having count(*) > 1; end;
create function sbt_09() returns setof text begin atomic select distinct y from sbt_t; end;
create function sbt_10() returns setof text begin atomic select y from sbt_t group by y order by y desc; end;
create function sbt_11() returns setof numeric begin atomic select sum(z) filter (where x > 1) from sbt_t group by y, x; end;
create function sbt_12() returns setof text begin atomic select distinct y from sbt_t order by y; end;
create function sbt_13() returns setof bigint begin atomic select count(*) from sbt_t group by 1 = 1, y; end;
create function sbt_14() returns setof bigint begin atomic select row_number() over (partition by y order by x) from sbt_t; end;
create function sbt_15() returns setof numeric begin atomic select sum(z) over w from sbt_t window w as (order by x); end;
create function sbt_16() returns setof bigint begin atomic select rank() over (order by x) + dense_rank() over (order by x) from sbt_t; end;
create function sbt_17() returns setof int begin atomic select x from sbt_t union select x from sbt_u; end;
create function sbt_18() returns setof int begin atomic select x from sbt_t union all select x from sbt_u except select 1; end;
create function sbt_19() returns setof int begin atomic values (1), (2); end;
create function sbt_20() returns setof text begin atomic select v.b from (values (1, 'a'), (2, 'b')) v(a, b); end;
create function sbt_21() returns setof int begin atomic with c as (select x from sbt_t) select x from c; end;
create function sbt_22() returns setof int begin atomic with c(k) as materialized (select x from sbt_t) select c.k from c, c d; end;
create function sbt_23() returns setof int begin atomic select s.a from (select x as a from sbt_t) s; end;
create function sbt_24() returns setof int begin atomic select x from sbt_t t, lateral (select t.x + 1 as q) l where l.q > 0; end;
create function sbt_25(p int) returns setof int begin atomic select x from sbt_t where x = all (select x from sbt_u where x > p); end;
create function sbt_26() returns setof int[] begin atomic select array(select x from sbt_u); end;
create function sbt_27() returns setof int begin atomic select g from generate_series(1, 3) g; end;
create function sbt_28() returns setof int begin atomic select generate_series(1, x) from sbt_t; end;
create function sbt_29() returns setof bigint begin atomic select o from unnest(array[1,2]) with ordinality as u(v, o); end;
create function sbt_30(n int) returns setof int begin atomic select x from sbt_t order by x limit n offset 1; end;
create function sbt_31(a int) returns void begin atomic insert into sbt_t values (a, 'q'); end;
create function sbt_32(a int) returns int begin atomic insert into sbt_t (y, x) values ('q', a) returning x + 1; end;
create function sbt_33(a int) returns void begin atomic insert into sbt_t values (a) on conflict (x) do update set y = excluded.y where sbt_t.z > 0; end;
create function sbt_34(a int) returns void begin atomic insert into sbt_t values (a) on conflict do nothing; end;
create function sbt_35() returns void begin atomic insert into sbt_t (x, y) values (1, 'a'), (2, 'b'); end;
create function sbt_36() returns void begin atomic insert into sbt_t (x, z) select x, x from sbt_u; end;
create function sbt_37(a int) returns void begin atomic update sbt_t set y = 'v', z = z + 1 where x = a; end;
create function sbt_38(a int) returns setof text begin atomic update sbt_t set z = 1, y = w from sbt_u where sbt_t.x = sbt_u.x returning w; end;
create function sbt_39(a int) returns void begin atomic delete from sbt_t where x = a; end;
create function sbt_40() returns setof int begin atomic delete from only sbt_t t using sbt_u where t.x = sbt_u.x returning t.x; end;
create function sbt_41(a int) returns int begin atomic select a; insert into sbt_u values (a); select count(*) from sbt_u; end;
create function sbt_42() returns setof text begin atomic select y from sbt_vw; end;
create function sbt_43() returns setof name begin atomic select relname from pg_class where relkind = 'r'; end;
create function sbt_44() returns setof int begin atomic select x from sbt_t t where x = (select max(u.x) from sbt_u u where u.w = t.y and exists (select 1 from sbt_u v where v.x = t.x)); end;
create function sbt_45() returns setof bigint begin atomic select (select count(*) from sbt_u where sbt_u.x = sbt_t.x) from sbt_t; end;
create function sbt_46() returns setof text begin atomic select y from sbt_t group by y, z having sum(x) > 2 and z > 1; end;
create function sbt_47() returns setof numeric begin atomic select sum(z) over (partition by y order by x rows between unbounded preceding and current row) from sbt_t; end;
create function sbt_48() returns setof int begin atomic select x from sbt_t union select x from sbt_u order by 1 limit 3; end;
create function sbt_49() returns setof int begin atomic select x from (select x, count(*) c from sbt_t group by x) s where c > 1; end;
create function sbt_50(a int) returns int begin atomic update sbt_t set z = (select max(x) from sbt_u) where x = a; select a; end;
create function sbt_51(a int) returns int return (select max(x) from sbt_t where x < a);
create function sbt_52() returns setof int begin atomic with c as (select x from sbt_t), d as (select x from c) select x from d where x in (select x from c); end;
create function sbt_53() returns setof int begin atomic select x from sbt_t where y like 'a%' order by y collate "C", x desc nulls last; end;
create function sbt_54() returns setof text begin atomic select string_agg(y, ',') from sbt_t; end;
create function sbt_55() returns setof numeric begin atomic select x + z from sbt_t; end;
create function sbt_56() returns setof int begin atomic select x from sbt_t where y is not null and z between 1 and 2; end;
create function sbt_57() returns setof bigint begin atomic select count(distinct y) from sbt_t; end;
create function sbt_58() returns setof text begin atomic select coalesce(y, w) from sbt_t left join sbt_u using (x); end;
create function sbt_59() returns setof int begin atomic select t.x from sbt_t t join sbt_u u on t.x = u.x join sbt_u v on v.x = u.x; end;
create function sbt_60() returns setof int begin atomic select x from sbt_t where exists (select 1 from sbt_u where sbt_u.x = sbt_t.x and sbt_u.w in (select y from sbt_t t2 where t2.x = sbt_t.x)); end;
create function sbt_61() returns setof text begin atomic select upper(y) from sbt_t order by upper(y); end;
create function sbt_62() returns setof int begin atomic select distinct on (y) x from sbt_t order by y, x; end;
create function sbt_63() returns setof text begin atomic select y from sbt_t group by y order by count(*); end;
create function sbt_64() returns setof int begin atomic select x from sbt_t intersect all select x from sbt_u; end;
create function sbt_65() returns setof numeric begin atomic select x from sbt_t union select z from sbt_t; end;
create function sbt_66() returns setof text begin atomic select 'a' union select 'b'; end;
create function sbt_67(p int) returns int return (select count(*) from sbt_t where x > p);
create function sbt_68() returns setof text begin atomic select string_agg(y, ',' order by y desc) from sbt_t; end;
create function sbt_69() returns setof bigint begin atomic select count(*) over (w order by x) from sbt_t window w as (partition by y); end;
create function sbt_70() returns setof numeric begin atomic select sum(z) filter (where x > 0) over () from sbt_t; end;
create function sbt_71() returns setof text begin atomic select y || 'a' from sbt_t group by y; end;
create function sbt_72() returns setof bigint begin atomic select count(*) from sbt_t having count(*) > 0; end;
create function sbt_73() returns setof int begin atomic with c as (select x from sbt_t) select x from sbt_t where x in (select x from c); end;
create function sbt_74() returns setof int begin atomic with c as (select x from sbt_t) select s.x from (select x from c) s; end;
create function sbt_75() returns setof bigint begin atomic select j.x from (sbt_t join sbt_u using (x)) j; end;
create function sbt_76() returns setof text begin atomic select w from sbt_t left join sbt_u on sbt_t.x = sbt_u.x where sbt_u.w is null; end;
create function sbt_77() returns setof int begin atomic select a.x from sbt_t a left join (sbt_t b left join sbt_u c on b.x = c.x) on a.x = b.x; end;
create function sbt_78() returns setof int begin atomic select g from sbt_t, generate_series(1, sbt_t.x) g; end;
create function sbt_79(p int) returns setof int begin atomic select column1 from (values (p), (p + 1)) v; end;
create function sbt_80() returns setof sbt_t begin atomic insert into sbt_t values (1) returning *; end;
create function sbt_81() returns void begin atomic insert into sbt_t default values; end;
create function sbt_82() returns void begin atomic update sbt_t set y = (select w from sbt_u limit 1); end;
create function sbt_83() returns setof sbt_t begin atomic delete from sbt_t returning *; end;
create function sbt_84() returns setof text begin atomic select v from sbt_t where v = 'a' and c > 'b' and d > 0; end;
create function sbt_85() returns setof int begin atomic select arr[1] from sbt_t; end;
create function sbt_86() returns setof sbt_t begin atomic select * from sbt_t; end;
create function sbt_87() returns setof int begin atomic select x from sbt_t order by y; end;
create function sbt_88() returns setof int begin atomic select x + 1 as q from sbt_t order by q; end;
create function sbt_89() returns setof int begin atomic select x from sbt_t limit all offset 2; end;
create function sbt_90() returns setof text begin atomic select upper(c) from sbt_t; end;
create function sbt_91() returns setof int begin atomic insert into sbt_t (x, v) values (1, 'abc') returning x; end;
create function sbt_92() returns setof bigint begin atomic select sbt_u.x from sbt_t join sbt_u using (x); end;
create function sbt_93() returns setof int begin atomic select sbt_t.x from sbt_t where exists (select from sbt_u); end;
create function sbt_94() returns setof int begin atomic select x from sbt_t t where (select count(*) from sbt_u where w = t.y) > 0 order by (select 1); end;
create function sbt_95() returns setof int begin atomic with recursive r(n) as (select 1 union all select n + 1 from r where n < 3) select n from r; end;
create function sbt_96() returns setof int begin atomic with recursive r as (select x from sbt_t union select r.x + 1 from r, sbt_t where r.x < sbt_t.x) select x from r; end;
create function sbt_97() returns setof int begin atomic with recursive c as (select 1 as q) select q from c; end;
create function sbt_98(a int) returns void begin atomic merge into sbt_t t using sbt_u u on t.x = u.x when matched and u.w = 'd' then delete when matched then update set y = u.w when not matched then insert (x, y) values (u.x, u.w); end;
create function sbt_99(a int) returns void begin atomic merge into sbt_t using (select x, w from sbt_u where x > a) s on sbt_t.x = s.x when not matched by source then delete when not matched then do nothing; end;
create function sbt_100() returns void begin atomic merge into sbt_t t using sbt_u u on t.x = u.x when not matched then insert values (u.x); end;
create function sbt_101() returns void begin atomic with c as (select 1 as q) insert into sbt_t select q from c; end;
create function sbt_102() returns void begin atomic insert into sbt_t values (1) on conflict (x) do update set z = excluded.z + sbt_t.z; end;
create function sbt_103(p text) returns setof text begin atomic update sbt_t set y = p where y <> p returning y; delete from sbt_u where w = p; end;
create function sbt_104() returns setof int[] begin atomic select array[1,2]; end;
create function sbt_105() returns setof int[] begin atomic select array[[1],[2]]; end;
create function sbt_106() returns setof bool begin atomic select (1,2) = (1,2); end;
create function sbt_107() returns setof bool begin atomic select 1 in (1,2,3); end;
create function sbt_108() returns setof bool begin atomic select 1 in (1, 2::bigint); end;
create function sbt_109() returns setof bool begin atomic select 'a' = any(array['a']); end;
create function sbt_110() returns setof text begin atomic select case 1 when 1 then 'a' else 'b' end; end;
create function sbt_111(p int) returns setof bool begin atomic select p not in (1, 2); end;
create function sbt_112() returns setof int begin atomic select x from unnest(array[1,2]) x; end;
create function sbt_113() returns setof bigint begin atomic select o from unnest(array[1,2]) with ordinality as u(v, o); end;
create function sbt_201() returns void begin atomic insert into sbt_t (x, y) values (1, default); end;
create function sbt_202() returns void begin atomic update sbt_t set y = default, c = default; end;
create function sbt_203() returns void begin atomic insert into sbt_t (x, c) values (2, default); end;
create function sbt_204() returns setof numeric begin atomic select sum(z) over (order by x rows between 1 preceding and current row) from sbt_t; end;
create function sbt_205() returns setof numeric begin atomic select sum(z) over (order by x rows between unbounded preceding and 2 following exclude current row) from sbt_t; end;
create function sbt_206() returns setof numeric begin atomic select sum(z) over (order by x groups 1 preceding) from sbt_t; end;
create function sbt_207() returns setof int begin atomic select first_value(x) over w from sbt_t window w as (partition by y order by z range between unbounded preceding and unbounded following); end;
create function sbt_208() returns setof date begin atomic select current_date; end;
create function sbt_209() returns setof int begin atomic select position('a' in y) from sbt_t; end;
create function sbt_210() returns setof text begin atomic select trim(both 'x' from y) from sbt_t; end;
create function sbt_211() returns setof timestamptz begin atomic select now(); end;
create function sbt_212() returns setof text begin atomic select substring(y from 2 for 3) from sbt_t; end;
SELECT proname, regexp_replace(prosqlbody::text, ':(relid|resorigtbl|vartype|consttype|paramtype|funcresulttype|aggtype|wintype|resulttype|typeId|row_typeid) [1-9][0-9]{4,}', ':\1 X', 'g') FROM pg_proc WHERE proname LIKE 'sbt\_%' ORDER BY 1;
DROP TABLE sbt_t, sbt_u, sbt_b CASCADE;
DROP DOMAIN sbt_dom CASCADE;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT oid::regprocedure p FROM pg_proc WHERE proname LIKE 'sbt\_%' LOOP EXECUTE 'DROP FUNCTION ' || r.p; END LOOP; END $$;
